const state={model:null,context:null,reservoir:null,rate:1.2,duration:20,year:12,percentile:50,layer:"pressure",limit:25,selectedIndex:null,basemap:true,showWells:true,showFaults:true,betaEnabled:false,betaRate:1,zetaEnabled:false,zetaRate:1,faultState:"semi-open",viewMode:"2d",view:{lon:9.95,lat:56.62,zoom:9},scene:{yaw:-.48,pitch:.58,scale:1}};
