const palettes={pressure:['#263344','#657ca5','#c27355','#f0ce6b'],margin:['#d05f55','#d5a85d','#9aaa75','#5d9f99'],geothermal:['#273945','#47777e','#62aaa7','#b8ddd0'],co2:['#202936','#315b6e','#62aaa7','#d7cf7a'],depth:['#d9cba1','#a98b68','#775b4d','#493d43'],thickness:['#2b3440','#5b7188','#8fb2ae','#e0cf8a'],permeability:['#312e43','#5b5688','#9a87b8','#e1c58e'],porosity:['#283942','#47777e','#70aaa4','#c7d8a2']};
