function populateReservoirs(){els.reservoir.innerHTML=state.model.reservoirs.filter(r=>r.assessment_type==='deep_geothermal').map(r=>`<option value="${r.id}">${r.name}</option>`).join('');els.reservoir.value='gassum';selectReservoir('gassum')}
