function renderFaults(){if(!state.showFaults)return'';return`<g class="faults">${state.context.faults.map((f,i)=>`<path class="fault-trace modelled ${state.faultState}" d="${pathFor(f.points)}"><title>${f.name} · all-fault ${state.faultState} scenario</title></path><path class="fault-hit" data-fault="${i}" d="${pathFor(f.points)}"/>`).join('')}</g>`}
